```js
async function getUser(id) {
  const rows = await db.query('SELECT * FROM users WHERE id = ?', [id]);
  if (!rows.length) throw new Error('Not found');
  return rows[0];
}
```

Callers use `try/catch` instead of checking the error argument:

```js
// before
getUser(id, (err, user) => {
  if (err) { /* handle */ }
  // use user
});

// after
try {
  const user = await getUser(id);
} catch (err) {
  // handle
}
```

One assumption: `db.query` already returns a promise. If it's still callback-based, wrap it first with `util.promisify`:

```js
const { promisify } = require('util');
const query = promisify(db.query).bind(db);

async function getUser(id) {
  const rows = await query('SELECT * FROM users WHERE id = ?', [id]);
  if (!rows.length) throw new Error('Not found');
  return rows[0];
}
```
